const fs = require('fs');
const os = require('os');
const download = require('download');
const {join, extname} = require("node:path");

const destDir = join(__dirname, "..", "native"); // target unpack dir
if (!fs.existsSync(destDir)) {
    fs.mkdirSync(destDir, {recursive: true});
}

const baseUrl = 'https://github.com/doo/scanbot-sdk-example-linux/releases/download';

const localBinaryDir = process.env.SBSDK_LOCAL_BINARY_DIR
if (localBinaryDir) {
    const files = fs.readdirSync(localBinaryDir);
    files.forEach(file => {
        const srcFile = join(localBinaryDir, file);
        const destFile = join(destDir, file);

        const supportedExtensions = [".so", ".node", ".dylib", ".dll"];
        if (fs.lstatSync(srcFile).isFile() && supportedExtensions.includes(extname(srcFile))) {
            console.log(`Copying ${srcFile} to ${destFile}`);
            fs.copyFileSync(srcFile, destFile);
        }
    });
} else {
    const version = process.env.npm_package_version;
    const systemArch = os.arch()
    const downloadArch = systemArch.includes("arm") || systemArch.includes("aarch64") ? "aarch64" : "x86_64";
    const url = `${baseUrl}/standalone-sdk%2Fv${version}/nodejs_addon-scanbotsdk-${version}-linux-${downloadArch}.tar.gz`
    download(url, destDir, {extract: true, followRedirect: true})
        .catch(err => {
            console.error(`Error: ${err.message}`);
            process.exit(1);
        });
}